    display:flex;
    justify-content:space-between;
    font-size:14px;
  }

  /* footer info text */
  .info{
    background:#fff;
    color:#333;
    margin-top:18px;
    border-radius:12px;
    padding:20px;
  }
  .info h2{ margin:0 0 12px; color:#222; }
  .info h3{ margin:16px 0 8px; color:#333; }
  .info p{ margin:0 0 10px; color:#444; line-height:1.5; }

  /* toast */
  .toast{
    position:fixed; left:12px; bottom:14px;
    background:#fff; color:#222; border-radius:12px; padding:12px 12px 12px 14px;
    box-shadow:0 14px 32px rgba(0,0,0,.25);
    display:none; align-items:center; gap:10px;
  }
  .toast .clear{
    background:#16a34a; color:#fff; border:none; border-radius:10px; padding:10px 12px; font-weight:700; cursor:pointer;
  }
  .toast .dot{ width:16px;height:16px;border-radius:50%; background:#7c3aed; }

  /* confetti */
  .confetti{
    pointer-events:none;
    position:fixed; left:0; right:0; bottom:0; top:0; overflow:hidden; display:none;
  }
  .confetti .piece{
    position:absolute; width:8px;height:16px; border-radius:2px;
    animation:fall 1800ms linear forwards;
    opacity:.9;
  }
  @keyframes fall{
    0%{ transform:translateY(-10vh) rotate(0); }
    100%{ transform:translateY(110vh) rotate(460deg); }
  }

  /* utility for clickable */
  .btn{ cursor:pointer; }
</style>
